package com.alsafa.native4;import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.widget.LinearLayout;import android.widget.TextView;import com.alsafa.native4.core.CoreDb;import com.alsafa.native4.core.Native4Services;public final class DirectPartSaleActivity extends Activity{private CoreDb db;private DirectPartSalePanelBinder binder;@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_direct_part_sale);db=new CoreDb(this);Native4Services services=new Native4Services(db,"native4-android-alpha");binder=new DirectPartSalePanelBinder(this,services,(TextView)findViewById(R.id.status),(LinearLayout)findViewById(R.id.pageHost));binder.show(true);String quick=getIntent().getStringExtra("quick_part_id");if(quick!=null&&!quick.trim().isEmpty())binder.selectQuickPart(quick);findViewById(R.id.pageBack).setOnClickListener(v->finish());}@Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(binder!=null)binder.onActivityResult(requestCode,resultCode,data);}}